exercises.solution:
cat > ~/bin/lustro.sh <<'EOF'
#!/bin/bash
src=${1%/}; dst=${2%/}
[ -d "$src" ] || { echo "brak katalogu $src"; exit 1; }
nazwa=$(basename "$src")
rsync -ain "$src/" "$dst/$nazwa/" | head -5
rsync -a --mkpath "$src/" "$dst/$nazwa/" && echo "zsynchronizowano $src -> $dst/$nazwa/"
EOF
chmod +x ~/bin/lustro.sh
~/bin/lustro.sh ~/projekty/sklep/ /srv/kopie/anna
